      let meta = await optional(() => vault.readJson(META));
      if (!meta) {
        meta = { version: 1, id: randomUUID(), createdAt: now() };
        await vault.writeJson(META, meta);
      }
      vault.id = validVaultMeta(meta).id;
      return vault;
    });
  }

  static async open(input, expectedId) {
